package gin

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestScratchLateWriteHeaderKeepsSentStatus(t *testing.T) {
	w := httptest.NewRecorder()
	c, _ := CreateTestContext(w)

	c.Writer.WriteHeader(http.StatusOK)
	c.Writer.WriteHeaderNow()
	c.Writer.WriteHeader(http.StatusUnauthorized)

	fmt.Println("Status() =", c.Writer.Status(), "Written() =", c.Writer.Written(), "Size() =", c.Writer.Size(), "client code =", w.Code)
	if got := c.Writer.Status(); got != http.StatusOK {
		t.Fatalf("Status() = %d, want 200", got)
	}
	if w.Code != http.StatusOK {
		t.Fatalf("client code = %d, want 200", w.Code)
	}

	// late WriteHeader after body write must also keep the sent status
	w2 := httptest.NewRecorder()
	c2, _ := CreateTestContext(w2)
	c2.Writer.WriteHeader(http.StatusCreated)
	_, _ = c2.Writer.Write([]byte("body"))
	c2.Writer.WriteHeader(http.StatusUnauthorized)
	if got := c2.Writer.Status(); got != http.StatusCreated {
		t.Fatalf("after body write Status() = %d, want 201", got)
	}
	if w2.Code != http.StatusCreated {
		t.Fatalf("client code = %d, want 201", w2.Code)
	}

	// status must still be settable before the header is written
	w3 := httptest.NewRecorder()
	c3, _ := CreateTestContext(w3)
	c3.Writer.WriteHeader(http.StatusOK)
	c3.Writer.WriteHeader(http.StatusUnauthorized)
	if got := c3.Writer.Status(); got != http.StatusUnauthorized {
		t.Fatalf("pre-write Status() = %d, want 401", got)
	}
}
